    margin-bottom: 1.5rem;
    font-weight: 700;
}

.footer-section p {
    font-size: 0.95rem;
    line-height: 1.6;
    opacity: 0.8;
}

.footer-section ul {
    list-style: none;
}

.footer-section ul li {
    margin-bottom: 1rem;
}

.footer-section a {
