}

.btn-secondary {
    background: var(--light-gray);
    color: var(--text-color);
}

.btn-secondary:hover {
    background: var(--medium-gray);
}

/* Section Styles */
.section-title {
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: 3rem;
    text-align: center;
    position: relative;
    padding-bottom: 1rem;
}

.section-title::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 50%;
    transform: translateX(-50%);
    width: 60px;
    height: 3px;
