    overflow: hidden;
    transition: var(--transition);
    border: 2px solid var(--accent-color);
}

.deal-card:hover {
    transform: scale(1.02);
    box-shadow: 0 12px 24px rgba(255, 107, 53, 0.2);
}

.deal-badge {
    position: absolute;
