.editorial-section {
    padding: 80px 20px;
    background: white;
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 2rem;
}

.editorial-card {
    border-radius: var(--border-radius);
