    right: 20px;
    top: 20px;
    font-size: 2rem;
    font-weight: 700;
    cursor: pointer;
    color: var(--text-color);
    z-index: 10;
    transition: var(--transition);
}

.close-btn:hover {
    color: var(--secondary-color);
    transform: rotate(90deg);
}

