});

// Render Featured Products
function renderFeaturedProducts() {
    const container = document.getElementById('featured-products');
    container.innerHTML = featuredProducts.map(product => `
        <div class="product-card" onclick="openProductModal(${product.id}, 'featured')">
            <img src="${product.image}" alt="${product.name}" class="product-image">
            <div class="product-info">
                <div class="product-category">${product.category}</div>
                <h3 class="product-name">${product.name}</h3>
                <p class="product-description">${product.description}</p>
                <div class="product-footer">
                    <span class="product-price">$${product.price.toFixed(2)}</span>
                    <span class="product-rating">${product.rating}</span>
                </div>
            </div>
        </div>
    `).join('');
}

// Render Deal Products
function renderDealProducts() {
    const container = document.getElementById('deals-products');
    container.innerHTML = dealProducts.map(product => `
        <div class="deal-card" onclick="openProductModal(${product.id}, 'deals')">
            <div class="deal-badge">${product.discount}% OFF</div>
            <div class="deal-image-container">
                <img src="${product.image}" alt="${product.name}" class="product-image">
            </div>
            <div class="deal-info">
                <div class="product-category">${product.category}</div>
                <h3 class="product-name">${product.name}</h3>
                <p class="product-description">${product.description}</p>
                <div class="price-row">
                    <span class="original-price">$${product.originalPrice.toFixed(2)}</span>
                    <span class="deal-price">$${product.price.toFixed(2)}</span>
                </div>
                <div class="deal-timer">⏱ Limited time offer</div>
            </div>
        </div>
    `).join('');
}

// Render Editorial Content
function renderEditorialContent() {
    const container = document.getElementById('editorial-content');
    container.innerHTML = editorialContent.map(article => `
        <div class="editorial-card" onclick="handleEditorialClick(${article.id})">
            <img src="${article.image}" alt="${article.title}" class="editorial-image">
            <div class="editorial-content-inner">
                <div class="editorial-date">${article.date}</div>
                <h3 class="editorial-title">${article.title}</h3>
                <p class="editorial-excerpt">${article.excerpt}</p>
                <a href="#" onclick="return false" class="read-more">Read Article</a>
            </div>
        </div>
    `).join('');
}

// Open Product Modal
function openProductModal(productId, source) {
    const products = source === 'featured' ? featuredProducts : dealProducts;
    const product = products.find(p => p.id === productId);

    if (!product) return;

    document.getElementById('modalProductImage').src = product.image;
    document.getElementById('modalProductName').textContent = product.name;
    document.getElementById('modalProductDescription').textContent = product.description;
    document.getElementById('modalProductRating').textContent = product.rating;
    document.getElementById('modalProductPrice').textContent = `$${product.price.toFixed(2)}`;

    if (product.originalPrice) {
        document.getElementById('modalOriginalPrice').style.display = 'inline';
        document.getElementById('modalOriginalPrice').textContent = `$${product.originalPrice.toFixed(2)}`;
    } else {
        document.getElementById('modalOriginalPrice').style.display = 'none';
    }

    document.getElementById('productModal').classList.add('active');
    document.getElementById('productModal').dataset.productId = productId;
    document.body.style.overflow = 'hidden';
}

// Close Product Modal
function closeProductModal(event) {
    if (event && event.target.id !== 'productModal') return;
    document.getElementById('productModal').classList.remove('active');
    document.body.style.overflow = 'auto';
}

// Add to Cart
function addToCart(event) {
    event.preventDefault();
    const productId = parseInt(document.getElementById('productModal').dataset.productId);
    const products = [...featuredProducts, ...dealProducts];
    const product = products.find(p => p.id === productId);

    if (product) {
        const cartItem = cart.find(item => item.id === productId);
        if (cartItem) {
            cartItem.quantity++;
        } else {
            cart.push({ ...product, quantity: 1 });
        }
        updateCartCount();
        saveCartToStorage();
        showNotification('Added to cart!');
        closeProductModal();
    }
}

// Update cart count in navbar
function updateCartCount() {
    const count = cart.reduce((total, item) => total + item.quantity, 0);
    document.querySelector('.cart-count').textContent = count;
}

// Save cart to localStorage
function saveCartToStorage() {
    localStorage.setItem('ecommerceCart', JSON.stringify(cart));
}

// Load cart from localStorage
function loadCartFromStorage() {
    const savedCart = localStorage.getItem('ecommerceCart');
    if (savedCart) {
        cart = JSON.parse(savedCart);
        updateCartCount();
    }
}

// Handle newsletter signup
function handleNewsletterSignup(event) {
    event.preventDefault();
    const email = event.target.querySelector('input[type="email"]').value;
    showNotification(`Thank you! Check your email at ${email}`);
    event.target.reset();
}

// Handle editorial click
function handleEditorialClick(articleId) {
    showNotification(`Opening article ${articleId}...`);
}

// Show notification
function showNotification(message) {
    // Create temporary notification
    const notification = document.createElement('div');
    notification.style.cssText = `
        position: fixed;
        top: 20px;
        right: 20px;
        background: #333;
        color: white;
        padding: 16px 24px;
        border-radius: 8px;
        font-weight: 600;
        z-index: 2000;
        animation: slideInRight 0.3s ease;
    `;
    notification.textContent = message;
    document.body.appendChild(notification);

    setTimeout(() => {
        notification.style.animation = 'slideOutRight 0.3s ease';
        setTimeout(() => notification.remove(), 300);
    }, 3000);
}

// Add animation styles
const style = document.createElement('style');
style.textContent = `
    @keyframes slideInRight {
        from {
            transform: translateX(400px);
            opacity: 0;
        }
        to {
            transform: translateX(0);
            opacity: 1;
        }
    }

    @keyframes slideOutRight {
        from {
            transform: translateX(0);
            opacity: 1;
        }
        to {
            transform: translateX(400px);
            opacity: 0;
        }
    }
`;
document.head.appendChild(style);
